import{_ as p,r as n,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"{% placeholder %} - October CMS - 4.x","titleTemplate":false,"description":"Twig Tag","frontmatter":{"subtitle":"Twig Tag"},"headers":[{"level":2,"title":"Replacing Content","slug":"replacing-content","link":"#replacing-content","children":[]},{"level":2,"title":"Handling Multiple Calls","slug":"handling-multiple-calls","link":"#handling-multiple-calls","children":[]},{"level":2,"title":"Default Placeholder Content","slug":"default-placeholder-content","link":"#default-placeholder-content","children":[]},{"level":2,"title":"Checking a Placeholder Exists","slug":"checking-a-placeholder-exists","link":"#checking-a-placeholder-exists","children":[]},{"level":2,"title":"Using Placeholders as Variables","slug":"using-placeholders-as-variables","link":"#using-placeholders-as-variables","children":[]},{"level":2,"title":"System Placeholders","slug":"system-placeholders","link":"#system-placeholders","children":[{"level":3,"title":"{% scripts %}","slug":"scripts","link":"#scripts","children":[{"level":4,"title":"Injecting Scripts","slug":"injecting-scripts","link":"#injecting-scripts","children":[]}]},{"level":3,"title":"{% styles %}","slug":"styles","link":"#styles","children":[{"level":4,"title":"Injecting Styles","slug":"injecting-styles","link":"#injecting-styles","children":[]}]},{"level":3,"title":"{% meta %}","slug":"meta","link":"#meta","children":[{"level":4,"title":"Injecting Meta Data","slug":"injecting-meta-data","link":"#injecting-meta-data","children":[]}]}]},{"level":2,"title":"Custom Attributes","slug":"custom-attributes","link":"#custom-attributes","children":[]}],"relativePath":"4.x/markup/tag/placeholder.md","filePath":"4.x/markup/tag/placeholder.md"}'),u={name:"4.x/markup/tag/placeholder.md"};function r(g,a,k,d,h,m){const t=n("pre-heading"),e=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"{% placeholder %}",-1)),s(e),a[1]||(a[1]=i(`<p>The <code>{% placeholder %}</code> tag will render a placeholder section which is generally <a href="./../../cms/themes/layouts.html">used inside Layouts</a>. This tag will return any placeholder contents that have been added using the <code>{% put %}</code> tag, or any default content that is defined (optional).</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> name <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Content can then be injected into the placeholder in any subsequent page or partial.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> name <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Place this text in the name placeholder<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="replacing-content"><a href="#replacing-content" class="header-anchor">#</a> Replacing Content</h2><p>By default, the <code>{% put %}</code> will append the content to the placeholder. Use the <code>replace</code> attribute to replace the contents instead.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> name replace <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Replace all the content inside with this<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="handling-multiple-calls"><a href="#handling-multiple-calls" class="header-anchor">#</a> Handling Multiple Calls</h2><p>In some cases you may call the <code>{% put %}</code> tag inside a partial to include some assets on the pages. Then, when including that partial multiple times on the same page, it can cause the script to be inserted twice. Including the <code>once</code> attribute will ensure the content is only set once per template. The cache key uses the CMS template filename to determine if it has already been inserted.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> scripts once <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>https://cdnjs.cloudflare.com/ajax/libs/tiny-slider/2.9.2/min/tiny-slider.js<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="default-placeholder-content"><a href="#default-placeholder-content" class="header-anchor">#</a> Default Placeholder Content</h2><p>Placeholders can have default content that can be either replaced or complemented by a page. If the <code>{% put %}</code> tag for a placeholder with default content is not defined on a page, the default placeholder content is displayed. Example placeholder definition in the layout template:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> sidebar default <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/contacts<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Contact us<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endplaceholder</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The page can inject more content to the placeholder. The <code>{% default %}</code> tag specifies a place where the default placeholder content should be displayed. If the tag is not used the placeholder content is completely replaced.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> sidebar <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/services<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Services<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">default</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="checking-a-placeholder-exists"><a href="#checking-a-placeholder-exists" class="header-anchor">#</a> Checking a Placeholder Exists</h2><p>In a layout template you can check if a placeholder content exists by using the <code>hasPlaceholder()</code> function. This lets you to generate different markup depending on whether the page provides a placeholder content. Example:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> hasPlaceholder<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>sidemenu<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token comment">&lt;!-- Markup for a page with a sidebar --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>row<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>col-md-3<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> sidemenu <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>col-md-9<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token comment">&lt;!-- Markup for a page without a sidebar --&gt;</span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="using-placeholders-as-variables"><a href="#using-placeholders-as-variables" class="header-anchor">#</a> Using Placeholders as Variables</h2><p>Placeholders can be useful for setting inherited variables, such as the active link in page navigation. The <code>{% put %}</code> tag allows you to set values directly. For example, setting the <code>activeNav</code> value to <strong>home</strong> inside a page template.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> activeNav <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&#39;</span>home<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The variable can be accessed inside the layout template using the <code>placeholder()</code> function. From this, we can determine the active link based on the value set by the page.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> active <span class="token operator">=</span> placeholder<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>activeNav<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> active <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>home<span class="token punctuation">&#39;</span></span> <span class="token operator">?</span> <span class="token string"><span class="token punctuation">&#39;</span>active<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Home<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> active <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>blog<span class="token punctuation">&#39;</span></span> <span class="token operator">?</span> <span class="token string"><span class="token punctuation">&#39;</span>active<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Blog<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> active <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>contact<span class="token punctuation">&#39;</span></span> <span class="token operator">?</span> <span class="token string"><span class="token punctuation">&#39;</span>active<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Contact<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>A default value (second argument) can be supplied as a fallback.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> active <span class="token operator">=</span> placeholder<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>activeNav<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>home<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="system-placeholders"><a href="#system-placeholders" class="header-anchor">#</a> System Placeholders</h2><p>October CMS defines static placeholders that are used by the system. Packages will use these placeholders to inject their dependencies to the page, either using the PHP or Twig interface.</p><h3 id="scripts"><a href="#scripts" class="header-anchor">#</a> {% scripts %}</h3><p>The <code>{% scripts %}</code> tag inserts JavaScript file references to scripts injected by the application. The tag is commonly defined before the closing BODY tag.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    ...
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">scripts</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><blockquote><p><strong>Note</strong>: This tag should appear once only in a given page cycle to prevent duplicated references.</p></blockquote><h4 id="injecting-scripts"><a href="#injecting-scripts" class="header-anchor">#</a> Injecting Scripts</h4><p>Links to JavaScript files can be programmatically injected in PHP either by <a href="./../../extend/cms-components.html">components</a> or <a href="./../../cms/themes/pages.html">pages</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;assets/js/app.js&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You can also inject raw markup to the <code>{% scripts %}</code> tag by using the <strong>scripts</strong> anonymous placeholder <a href="./../../cms/themes/layouts.html">in the layout</a>. Use the <code>{% put %}</code> tag in pages or layouts to add content to the placeholder.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> scripts <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text/javascript<span class="token punctuation">&quot;</span></span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/themes/demo/assets/js/menu.js<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="styles"><a href="#styles" class="header-anchor">#</a> {% styles %}</h3><p>The <code>{% styles %}</code> tag renders CSS links to stylesheet files injected by the application. The tag is commonly defined in the HEAD section of a page or layout.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    ...
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">styles</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><blockquote><p><strong>Note</strong>: This tag should appear once only in a given page cycle to prevent duplicated references.</p></blockquote><h4 id="injecting-styles"><a href="#injecting-styles" class="header-anchor">#</a> Injecting Styles</h4><p>Links to StyleSheet files can be programmatically injected in PHP either by <a href="./../../extend/cms-components.html">components</a> or <a href="./../../cms/themes/pages.html">pages</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addCss</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;assets/css/hello.css&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You can also inject raw markup to the <code>{% styles %}</code> tag by using the <strong>styles</strong> anonymous placeholder <a href="./../../cms/themes/layouts.html">in the layout</a>. Use the <code>{% put %}</code> tag in pages or layouts to add content to the placeholder.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> styles <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>link</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/themes/demo/assets/css/page.css<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rel</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>stylesheet<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="meta"><a href="#meta" class="header-anchor">#</a> {% meta %}</h3><p>The <code>{% meta %}</code> tag renders meta content, such as open graph information. The tag is commonly defined in the HEAD section of a page or layout, placed before the styles and scripts.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">meta</span> <span class="token delimiter punctuation">%}</span></span>
    ...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><blockquote><p><strong>Note</strong>: This tag should appear once only in a given page cycle to prevent duplicated references.</p></blockquote><h4 id="injecting-meta-data"><a href="#injecting-meta-data" class="header-anchor">#</a> Injecting Meta Data</h4><p>You can inject raw markup to the <code>{% meta %}</code> tag by using the <strong>meta</strong> anonymous placeholder <a href="./../../cms/themes/layouts.html">in the layout</a>. Use the <code>{% put %}</code> tag in pages or layouts to add content to the placeholder.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> meta <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>turbo-visit-control<span class="token punctuation">&quot;</span></span> <span class="token attr-name">content</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>error<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="custom-attributes"><a href="#custom-attributes" class="header-anchor">#</a> Custom Attributes</h2><p>The <code>placeholder</code> tag accepts two optional attributes &amp;mdash; <code>title</code> and <code>type</code>. The <code>title</code> attribute is not used by the CMS itself, but could be used by other plugins. The type attribute manages the placeholder type. There are two types supported at the moment &amp;mdash; <strong>text</strong> and <strong>html</strong>. The content of text placeholders is escaped before it&#39;s displayed. The title and type attributes should be defined after the placeholder name and the <code>default</code> attribute, if it&#39;s presented. Example:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> ordering title<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Ordering information<span class="token punctuation">&quot;</span></span> type<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>text<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Example of a placeholder with a default content, title and type attributes.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> ordering default title<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Ordering information<span class="token punctuation">&quot;</span></span> type<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>text<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
    There is no ordering information for this product.
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endplaceholder</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div>`,57))])}const v=p(u,[["render",r]]);export{y as __pageData,v as default};
